Plan: use the active sheet as the answer sheet, read A2:A8 from the cached workbook values, and extract digit characters while preserving leading zeros when present. Sort the unique digits ascending, write up to five digits into C:G for each row, and clear the remaining answer cells.

```python
import shutil
import openpyxl

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

ws = wb.active
if ws is None:
    ws = wb.worksheets[0]

def has_data(sheet):
    return any(sheet.cell(row=r, column=1).value is not None for r in range(2, 9))

source_title = None
if ws.title in vals.sheetnames and has_data(vals[ws.title]):
    source_title = ws.title
elif "Sheet2" in vals.sheetnames:
    source_title = "Sheet2"
else:
    source_title = vals.sheetnames[0]

source_vals = vals[source_title]
source_wb = wb[source_title] if source_title in wb.sheetnames else wb[ws.title]

def max_zero_run(fmt):
    best = cur = 0
    if not fmt:
        return 0
    for ch in fmt:
        if ch == "0":
            cur += 1
            if cur > best:
                best = cur
        else:
            cur = 0
    return best

def unique_digits(value, fmt):
    if value is None or isinstance(value, bool):
        return []

    if isinstance(value, (int, float)):
        if isinstance(value, float):
            s = str(int(value)) if value.is_integer() else str(value)
        else:
            s = str(value)

        if s.lstrip("-").isdigit():
            z = max_zero_run(fmt)
            if z > len(s):
                s = s.zfill(z)
    else:
        s = str(value)

    return sorted({ch for ch in s if ch.isdigit()})

for r in range(2, 9):
    fmt = source_wb.cell(row=r, column=1).number_format
    digits = unique_digits(source_vals.cell(row=r, column=1).value, fmt)

    for c in range(3, 8):
        ws.cell(row=r, column=c).value = None

    for i, d in enumerate(digits[:5]):
        ws.cell(row=r, column=3 + i).value = int(d)

    print(r, digits)

wb.save(OUT)
